import { request } from '../../api/client';
import type { Cart, Discount } from './cart';

export function loadCart(): Promise<Cart> {
  return request<Cart>('/cart');
}

export function saveCart(cart: Cart): Promise<Cart> {
  return request<Cart>('/cart', { method: 'PUT', body: JSON.stringify(cart) });
}

export async function checkDiscount(code: string): Promise<Discount> {
  const { percent } = await request<{ percent: number }>('/discounts/check', {
    method: 'POST',
    body: JSON.stringify({ code }),
  });
  if (!Number.isFinite(percent) || percent < 0 || percent > 100) throw new Error(`Bad discount percent: ${percent}`);
  return { code, percent };
}
